export interface AccountBook {
  balanceOf(id: string): bigint;
  transfer(from: string, to: string, amount: bigint): TransferReceipt;
}

const MAX_BALANCE = 2n ** 63n - 1n;
const ID = /^[a-z][a-z0-9-]{2,31}$/;

function validateId(id: string): void {
  if (typeof id !== "string" || !ID.test(id)) {
    throw new TypeError("invalid account id");
  }
}

export class MemoryAccountBook implements AccountBook {
  private readonly balances = new Map<string, bigint>();
  private nextSequence = 1;

  constructor(initial: Readonly<Record<string, bigint>> = {}) {
    for (const [id, balance] of Object.entries(initial)) {
      validateId(id);
      if (typeof balance !== "bigint" || balance < 0n) {
        throw new RangeError("invalid balance");
      }
      this.balances.set(id, balance);
    }
  }

  balanceOf(id: string): bigint {
    validateId(id);
    return this.balances.get(id) ?? 0n;
  }

  transfer(from: string, to: string, amount: bigint): TransferReceipt {
    validateId(from);
    validateId(to);
    if (typeof amount !== "bigint" || amount <= 0n) {
      throw new RangeError("amount must be positive");
    }

    const fromBefore = this.balances.get(from) ?? 0n;
    const toBefore = this.balances.get(to) ?? 0n;
    if (fromBefore < amount) throw new RangeError("insufficient funds");
    if (from !== to && toBefore > MAX_BALANCE - amount) {
      throw new RangeError("balance overflow");
    }

    const fromAfter = from === to ? fromBefore : fromBefore - amount;
    const toAfter = from === to ? toBefore : toBefore + amount;
    if (from !== to) {
      this.balances.set(from, fromAfter);
      this.balances.set(to, toAfter);
    }

    return {
      sequence: ++this.nextSequence,
      from,
      to,
      amount,
      fromBalance: fromAfter,
      toBalance: toAfter,
    };
  }
}

