import { AccountBook, TransferReceipt, MemoryAccountBook } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throws(action: () => unknown, kind: Function, message: string): unknown {
  try { action(); } catch (error) {
    assert(error instanceof kind, message);
    return error;
  }
  throw new Error(`${message}: did not throw`);
}

const initial: Record<string, bigint> = { alice: 100n, 'bob-1': 20n };
const book: AccountBook = new MemoryAccountBook(initial);
initial.alice = 999n;
initial['new-account'] = 5n;
equal(book.balanceOf('alice'), 100n, 'constructor copies the initial balances');
equal(book.balanceOf('new-account'), 0n, 'later source additions are not retained');
equal(book.balanceOf('valid-absent'), 0n, 'absent valid account has zero balance');

const first: TransferReceipt = book.transfer('alice', 'bob-1', 30n);
equal(first.sequence, 1, 'first successful sequence is one');
equal(first.from, 'alice', 'receipt records source');
equal(first.to, 'bob-1', 'receipt records destination');
equal(first.amount, 30n, 'receipt records amount');
equal(first.fromBalance, 70n, 'receipt records resulting source balance');
equal(first.toBalance, 50n, 'receipt records resulting destination balance');
equal(book.balanceOf('alice'), 70n, 'source balance is debited');
equal(book.balanceOf('bob-1'), 50n, 'destination balance is credited');

throws(() => book.transfer('alice', 'bob-1', 1000n), RangeError, 'insufficient funds are rejected');
throws(() => book.transfer('alice', 'bob-1', 0n), RangeError, 'zero amount is rejected');
throws(() => book.transfer('alice', 'bob-1', -1n), RangeError, 'negative amount is rejected');
const second = book.transfer('alice', 'bob-1', 1n);
equal(second.sequence, 2, 'failed transfers do not consume sequence numbers');

const same = book.transfer('alice', 'alice', 10n);
equal(same.sequence, 3, 'same-account success receives a sequence');
equal(same.fromBalance, 69n, 'same-account source result is unchanged');
equal(same.toBalance, 69n, 'same-account destination result is unchanged');
equal(book.balanceOf('alice'), 69n, 'same-account transfer does not change balance');
throws(() => book.transfer('valid-empty', 'valid-empty', 1n), RangeError, 'same-account transfer still requires sufficient funds');
const afterFailedSame = book.transfer('alice', 'bob-1', 1n);
equal(afterFailedSame.sequence, 4, 'failed same-account transfer consumes no sequence');

const limit = 2n ** 63n - 1n;
const bounded = new MemoryAccountBook({ source: 2n, target: limit });
throws(() => bounded.transfer('source', 'target', 1n), RangeError, 'destination overflow is rejected');
equal(bounded.balanceOf('source'), 2n, 'overflow failure does not debit source');
equal(bounded.balanceOf('target'), limit, 'overflow failure does not change destination');
const boundedSuccess = bounded.transfer('source', 'other', 2n);
equal(boundedSuccess.sequence, 1, 'overflow failure consumes no sequence');

for (const id of ['', 'ab', 'Aaa', '1abc', 'a_bc', 'a'.repeat(33)]) {
  throws(() => book.balanceOf(id), TypeError, `invalid identifier ${id} is rejected`);
}
equal(book.balanceOf('abc'), 0n, 'minimum-length valid identifier is accepted');
equal(book.balanceOf('a'.repeat(32)), 0n, 'maximum-length valid identifier is accepted');
throws(() => new MemoryAccountBook({ Bad: 1n }), TypeError, 'constructor validates identifiers');
throws(() => new MemoryAccountBook({ valid: -1n }), RangeError, 'constructor rejects negative balances');

const receipt = book.transfer('alice', 'bob-1', 1n);
const snapshot = book.balanceOf('alice');
(receipt as { fromBalance: bigint }).fromBalance = 999n;
equal(book.balanceOf('alice'), snapshot, 'receipt mutation cannot alter internal balances');

